{
  "$defs": {
    "canonicalBinding": {
      "additionalProperties": false,
      "properties": {
        "authority_effect": {
          "const": "none"
        },
        "definition_ref": {
          "enum": [
            "CAV2-D65",
            "CAV2-D67"
          ]
        },
        "local_use": {
          "$ref": "#/$defs/text"
        },
        "selector_sha256": {
          "pattern": "^[0-9a-f]{64}$",
          "type": "string"
        },
        "source_ref": {
          "pattern": "^CAP-SEL-",
          "type": "string"
        }
      },
      "required": [
        "definition_ref",
        "source_ref",
        "selector_sha256",
        "local_use",
        "authority_effect"
      ],
      "type": "object"
    },
    "coverageBasis": {
      "additionalProperties": false,
      "properties": {
        "completeness_claim": {
          "$ref": "#/$defs/text"
        },
        "external_agent_capability_reference_count": {
          "const": 0
        },
        "historical_candidate_copies_excluded": {
          "const": true
        },
        "posture": {
          "const": "exact-source-bounded"
        },
        "product_capability_count": {
          "const": 12
        }
      },
      "required": [
        "posture",
        "product_capability_count",
        "external_agent_capability_reference_count",
        "completeness_claim",
        "historical_candidate_copies_excluded"
      ],
      "type": "object"
    },
    "definitionRegistry": {
      "additionalProperties": false,
      "properties": {
        "authority_effect": {
          "const": "none"
        },
        "canonical_bindings": {
          "items": {
            "$ref": "#/$defs/canonicalBinding"
          },
          "maxItems": 2,
          "minItems": 2,
          "type": "array"
        },
        "local_terms": {
          "items": {
            "$ref": "#/$defs/localTerm"
          },
          "minItems": 1,
          "type": "array"
        },
        "schema_ref": {
          "const": "schemas/durable-storage.schema.json#/$defs/definitionRegistry"
        },
        "schema_version": {
          "const": "cav2-durable-storage-definitions/v1"
        }
      },
      "required": [
        "schema_ref",
        "schema_version",
        "canonical_bindings",
        "local_terms",
        "authority_effect"
      ],
      "type": "object"
    },
    "id": {
      "pattern": "^[A-Z0-9][A-Z0-9._-]+$",
      "type": "string"
    },
    "localTerm": {
      "additionalProperties": false,
      "properties": {
        "canonical_status": {
          "const": "package-local-candidate"
        },
        "forbidden_collapse": {
          "$ref": "#/$defs/text"
        },
        "meaning": {
          "$ref": "#/$defs/text"
        },
        "owner_route": {
          "$ref": "#/$defs/text"
        },
        "term": {
          "$ref": "#/$defs/text"
        },
        "term_id": {
          "pattern": "^DS-TERM-",
          "type": "string"
        }
      },
      "required": [
        "term_id",
        "term",
        "meaning",
        "owner_route",
        "canonical_status",
        "forbidden_collapse"
      ],
      "type": "object"
    },
    "node": {
      "additionalProperties": false,
      "properties": {
        "authority_effect": {
          "const": "none"
        },
        "candidate_status": {
          "enum": [
            "candidate",
            "projected",
            "deferred",
            "blocked"
          ]
        },
        "claim": {
          "$ref": "#/$defs/text"
        },
        "commitment_confidence": {
          "enum": [
            "low",
            "conditional",
            "committed"
          ]
        },
        "evidence_confidence": {
          "enum": [
            "low",
            "medium",
            "high"
          ]
        },
        "forbidden_collapse": {
          "$ref": "#/$defs/text"
        },
        "id": {
          "$ref": "#/$defs/id"
        },
        "label": {
          "$ref": "#/$defs/text"
        },
        "open_questions": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "owner_route": {
          "$ref": "#/$defs/text"
        },
        "plain_language": {
          "$ref": "#/$defs/text"
        },
        "role": {
          "enum": [
            "product_projection",
            "product_capability",
            "actor",
            "domain_concept",
            "input_contract",
            "output_contract",
            "policy",
            "business_rule",
            "outcome"
          ]
        },
        "source_refs": {
          "items": {
            "$ref": "#/$defs/sourceRef"
          },
          "minItems": 1,
          "type": "array"
        }
      },
      "required": [
        "id",
        "label",
        "role",
        "plain_language",
        "claim",
        "source_refs",
        "owner_route",
        "candidate_status",
        "evidence_confidence",
        "commitment_confidence",
        "authority_effect",
        "forbidden_collapse",
        "open_questions"
      ],
      "type": "object"
    },
    "nodeRegistry": {
      "additionalProperties": false,
      "properties": {
        "authority_effect": {
          "const": "none"
        },
        "nodes": {
          "items": {
            "$ref": "#/$defs/node"
          },
          "minItems": 1,
          "type": "array"
        },
        "schema_ref": {
          "const": "schemas/durable-storage.schema.json#/$defs/nodeRegistry"
        },
        "schema_version": {
          "const": "cav2-durable-storage-nodes/v1"
        }
      },
      "required": [
        "schema_ref",
        "schema_version",
        "nodes",
        "authority_effect"
      ],
      "type": "object"
    },
    "obligation": {
      "additionalProperties": false,
      "properties": {
        "obligation_id": {
          "pattern": "^DS-OBL-",
          "type": "string"
        },
        "state": {
          "enum": [
            "model-checkable",
            "not_evaluable"
          ]
        },
        "statement": {
          "$ref": "#/$defs/text"
        }
      },
      "required": [
        "obligation_id",
        "statement",
        "state"
      ],
      "type": "object"
    },
    "obligationRegistry": {
      "additionalProperties": false,
      "properties": {
        "aggregate_state": {
          "const": "not_evaluable"
        },
        "obligations": {
          "items": {
            "$ref": "#/$defs/obligation"
          },
          "minItems": 1,
          "type": "array"
        },
        "registry_id": {
          "const": "CA2-CAP-OBLIGATIONS-DURABLE-STORAGE"
        }
      },
      "required": [
        "registry_id",
        "aggregate_state",
        "obligations"
      ],
      "type": "object"
    },
    "ontologySelection": {
      "additionalProperties": false,
      "properties": {
        "confidence": {
          "const": "high"
        },
        "excluded_types": {
          "const": [
            "system-runtime",
            "business-system-bridge"
          ]
        },
        "reason": {
          "$ref": "#/$defs/text"
        },
        "source": {
          "const": "inferred"
        }
      },
      "required": [
        "source",
        "confidence",
        "reason",
        "excluded_types"
      ],
      "type": "object"
    },
    "productCapabilitySupport": {
      "additionalProperties": false,
      "properties": {
        "adoption_state": {
          "const": "not-adopted"
        },
        "authority_effect": {
          "const": "none"
        },
        "capability_ref": {
          "const": "CA2-CAP-PRESERVE-DURABLE-CAPABILITY-STATE"
        },
        "construction_stage": {
          "const": "business-ontology-candidate"
        },
        "instance_status": {
          "const": "candidate"
        },
        "obligation_registry": {
          "$ref": "#/$defs/obligationRegistry"
        },
        "realization_binding": {
          "$ref": "#/$defs/realizationBinding"
        },
        "schema_ref": {
          "const": "schemas/durable-storage.schema.json#/$defs/productCapabilitySupport"
        },
        "schema_version": {
          "const": "cav2-durable-storage-product-capability-support/v1"
        }
      },
      "required": [
        "schema_ref",
        "schema_version",
        "capability_ref",
        "instance_status",
        "adoption_state",
        "construction_stage",
        "realization_binding",
        "obligation_registry",
        "authority_effect"
      ],
      "type": "object"
    },
    "profile": {
      "additionalProperties": false,
      "properties": {
        "authority_effect": {
          "const": "none"
        },
        "blocked_outputs": {
          "items": {
            "$ref": "#/$defs/text"
          },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "branch": {
          "const": "business"
        },
        "candidate_status": {
          "const": "candidate"
        },
        "construction_stage": {
          "const": "business-ontology-candidate"
        },
        "definition_registry": {
          "const": "definitions.json"
        },
        "materialization": {
          "const": "package-required"
        },
        "meaning_owner": {
          "$ref": "#/$defs/text"
        },
        "node_registry": {
          "const": "nodes.json"
        },
        "ontology_id": {
          "const": "cav2.durable-storage.business"
        },
        "ontology_type": {
          "const": "business-domain"
        },
        "ontology_type_selection": {
          "$ref": "#/$defs/ontologySelection"
        },
        "package_id": {
          "const": "cav2.durable-storage"
        },
        "package_owner": {
          "$ref": "#/$defs/text"
        },
        "package_root": {
          "const": "cyberAlchemy-v2/durable-storage"
        },
        "product_capability": {
          "const": "product-capability.json"
        },
        "product_capability_ref": {
          "const": "CA2-CAP-PRESERVE-DURABLE-CAPABILITY-STATE"
        },
        "product_capability_support": {
          "const": "product-capability-support.json"
        },
        "product_ref": {
          "const": "CA2-PRODUCT-CYBERALCHEMY"
        },
        "relation_registry": {
          "const": "relations.json"
        },
        "residue_registry": {
          "const": "residue.json"
        },
        "runtime_registration_status": {
          "const": "registered-read-only-candidate"
        },
        "schema_path": {
          "const": "schemas/durable-storage.schema.json"
        },
        "schema_ref": {
          "const": "schemas/durable-storage.schema.json#/$defs/profile"
        },
        "schema_version": {
          "const": "cav2-durable-storage-profile/v1"
        },
        "source_registry": {
          "const": "sources.json"
        },
        "storage_class_registry": {
          "const": "storage-classes.json"
        },
        "storage_requirement_registry": {
          "const": "storage-requirements.json"
        },
        "title": {
          "$ref": "#/$defs/text"
        },
        "validator_path": {
          "const": "scripts/validate.py"
        },
        "visibility": {
          "const": "private"
        }
      },
      "required": [
        "schema_ref",
        "schema_version",
        "package_id",
        "ontology_id",
        "title",
        "ontology_type",
        "ontology_type_selection",
        "branch",
        "materialization",
        "package_root",
        "package_owner",
        "meaning_owner",
        "product_ref",
        "product_capability_ref",
        "visibility",
        "candidate_status",
        "construction_stage",
        "runtime_registration_status",
        "authority_effect",
        "source_registry",
        "definition_registry",
        "product_capability",
        "product_capability_support",
        "storage_class_registry",
        "storage_requirement_registry",
        "node_registry",
        "relation_registry",
        "residue_registry",
        "schema_path",
        "validator_path",
        "blocked_outputs"
      ],
      "type": "object"
    },
    "realizationBinding": {
      "additionalProperties": false,
      "properties": {
        "authority_effect": {
          "const": "none"
        },
        "binding_id": {
          "const": "CA2-CAP-BIND-DURABLE-STORAGE-UNSELECTED"
        },
        "blockers": {
          "items": {
            "$ref": "#/$defs/text"
          },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "implementation_ref": {
          "type": "null"
        },
        "provider_ref": {
          "type": "null"
        },
        "state": {
          "const": "not_evaluable"
        },
        "system_ontology_ref": {
          "type": "null"
        }
      },
      "required": [
        "binding_id",
        "state",
        "system_ontology_ref",
        "provider_ref",
        "implementation_ref",
        "blockers",
        "authority_effect"
      ],
      "type": "object"
    },
    "relation": {
      "additionalProperties": false,
      "properties": {
        "authority_effect": {
          "const": "none"
        },
        "forbidden_collapse": {
          "$ref": "#/$defs/text"
        },
        "id": {
          "pattern": "^DS-REL-",
          "type": "string"
        },
        "owner_route": {
          "$ref": "#/$defs/text"
        },
        "source": {
          "$ref": "#/$defs/id"
        },
        "source_refs": {
          "items": {
            "$ref": "#/$defs/sourceRef"
          },
          "minItems": 1,
          "type": "array"
        },
        "target": {
          "$ref": "#/$defs/id"
        },
        "type": {
          "pattern": "^[a-z][a-z0-9_]*$",
          "type": "string"
        }
      },
      "required": [
        "id",
        "type",
        "source",
        "target",
        "source_refs",
        "owner_route",
        "authority_effect",
        "forbidden_collapse"
      ],
      "type": "object"
    },
    "relationRegistry": {
      "additionalProperties": false,
      "properties": {
        "authority_effect": {
          "const": "none"
        },
        "relation_vocabulary": {
          "items": {
            "$ref": "#/$defs/relationType"
          },
          "minItems": 1,
          "type": "array"
        },
        "relations": {
          "items": {
            "$ref": "#/$defs/relation"
          },
          "minItems": 1,
          "type": "array"
        },
        "schema_ref": {
          "const": "schemas/durable-storage.schema.json#/$defs/relationRegistry"
        },
        "schema_version": {
          "const": "cav2-durable-storage-relations/v1"
        }
      },
      "required": [
        "schema_ref",
        "schema_version",
        "relation_vocabulary",
        "relations",
        "authority_effect"
      ],
      "type": "object"
    },
    "relationType": {
      "additionalProperties": false,
      "properties": {
        "forbidden_collapse": {
          "$ref": "#/$defs/text"
        },
        "meaning": {
          "$ref": "#/$defs/text"
        },
        "source_roles": {
          "items": {
            "type": "string"
          },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "target_roles": {
          "items": {
            "type": "string"
          },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "type": {
          "pattern": "^[a-z][a-z0-9_]*$",
          "type": "string"
        }
      },
      "required": [
        "type",
        "source_roles",
        "target_roles",
        "meaning",
        "forbidden_collapse"
      ],
      "type": "object"
    },
    "residue": {
      "additionalProperties": false,
      "properties": {
        "authority_effect": {
          "const": "none"
        },
        "description": {
          "$ref": "#/$defs/text"
        },
        "evidence_refs": {
          "items": {
            "pattern": "^CAP-SEL-",
            "type": "string"
          },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "label": {
          "$ref": "#/$defs/text"
        },
        "next_action": {
          "$ref": "#/$defs/text"
        },
        "owner_route": {
          "$ref": "#/$defs/text"
        },
        "residue_id": {
          "pattern": "^CAP-RES-DURABLE-STORAGE-",
          "type": "string"
        },
        "status": {
          "enum": [
            "open",
            "deferred",
            "blocked",
            "closed"
          ]
        },
        "subject_refs": {
          "items": {
            "$ref": "#/$defs/id"
          },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        }
      },
      "required": [
        "residue_id",
        "label",
        "description",
        "status",
        "owner_route",
        "next_action",
        "subject_refs",
        "evidence_refs",
        "authority_effect"
      ],
      "type": "object"
    },
    "residueRegistry": {
      "additionalProperties": false,
      "properties": {
        "authority_effect": {
          "const": "none"
        },
        "residue": {
          "items": {
            "$ref": "#/$defs/residue"
          },
          "type": "array"
        },
        "schema_ref": {
          "const": "schemas/durable-storage.schema.json#/$defs/residueRegistry"
        },
        "schema_version": {
          "const": "cav2-durable-storage-residue/v1"
        }
      },
      "required": [
        "schema_ref",
        "schema_version",
        "residue",
        "authority_effect"
      ],
      "type": "object"
    },
    "source": {
      "additionalProperties": false,
      "properties": {
        "owner_route": {
          "$ref": "#/$defs/text"
        },
        "path": {
          "$ref": "#/$defs/text"
        },
        "posture": {
          "$ref": "#/$defs/text"
        },
        "selection_kind": {
          "enum": [
            "whole-file",
            "markdown-section"
          ]
        },
        "selector": {
          "$ref": "#/$defs/text"
        },
        "sha256": {
          "pattern": "^[0-9a-f]{64}$",
          "type": "string"
        },
        "source_id": {
          "pattern": "^CAP-SEL-",
          "type": "string"
        }
      },
      "required": [
        "source_id",
        "path",
        "selection_kind",
        "selector",
        "sha256",
        "posture",
        "owner_route"
      ],
      "type": "object"
    },
    "sourceRef": {
      "additionalProperties": false,
      "properties": {
        "selector": {
          "$ref": "#/$defs/text"
        },
        "source_id": {
          "pattern": "^CAP-SEL-",
          "type": "string"
        }
      },
      "required": [
        "source_id",
        "selector"
      ],
      "type": "object"
    },
    "sourceRegistry": {
      "additionalProperties": false,
      "properties": {
        "schema_ref": {
          "const": "schemas/durable-storage.schema.json#/$defs/sourceRegistry"
        },
        "schema_version": {
          "const": "cav2-durable-storage-sources/v1"
        },
        "sources": {
          "items": {
            "$ref": "#/$defs/source"
          },
          "minItems": 1,
          "type": "array"
        }
      },
      "required": [
        "schema_ref",
        "schema_version",
        "sources"
      ],
      "type": "object"
    },
    "storageClass": {
      "additionalProperties": false,
      "properties": {
        "authority_effect": {
          "const": "none"
        },
        "authority_role": {
          "enum": [
            "source",
            "evidence",
            "operational-state",
            "artifact",
            "projection",
            "secret-reference",
            "ephemeral"
          ]
        },
        "class_id": {
          "pattern": "^DS-CLASS-",
          "type": "string"
        },
        "excluded_uses": {
          "items": {
            "$ref": "#/$defs/text"
          },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "label": {
          "$ref": "#/$defs/text"
        },
        "mutability": {
          "enum": [
            "revision-controlled",
            "append-only",
            "immutable",
            "replaceable",
            "reference-only"
          ]
        },
        "rebuildable": {
          "type": "boolean"
        },
        "required_evidence": {
          "items": {
            "$ref": "#/$defs/text"
          },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "semantics": {
          "$ref": "#/$defs/text"
        }
      },
      "required": [
        "class_id",
        "label",
        "authority_role",
        "mutability",
        "rebuildable",
        "semantics",
        "required_evidence",
        "excluded_uses",
        "authority_effect"
      ],
      "type": "object"
    },
    "storageClassRegistry": {
      "additionalProperties": false,
      "properties": {
        "authority_effect": {
          "const": "none"
        },
        "classes": {
          "items": {
            "$ref": "#/$defs/storageClass"
          },
          "minItems": 1,
          "type": "array"
        },
        "schema_ref": {
          "const": "schemas/durable-storage.schema.json#/$defs/storageClassRegistry"
        },
        "schema_version": {
          "const": "cav2-durable-storage-classes/v1"
        }
      },
      "required": [
        "schema_ref",
        "schema_version",
        "classes",
        "authority_effect"
      ],
      "type": "object"
    },
    "storageRequirement": {
      "additionalProperties": false,
      "properties": {
        "artifact_kinds": {
          "items": {
            "pattern": "^[a-z][a-z0-9-]*$",
            "type": "string"
          },
          "type": "array",
          "uniqueItems": true
        },
        "authority_effect": {
          "const": "none"
        },
        "binding_state": {
          "enum": [
            "unselected",
            "external-owner"
          ]
        },
        "claim_limit": {
          "$ref": "#/$defs/text"
        },
        "durability_class_refs": {
          "items": {
            "pattern": "^DS-CLASS-",
            "type": "string"
          },
          "type": "array",
          "uniqueItems": true
        },
        "evidence_refs": {
          "items": {
            "pattern": "^CAP-SEL-",
            "type": "string"
          },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "need_posture": {
          "enum": [
            "evidenced-existing",
            "required-before-runtime",
            "mixed-existing-and-future",
            "derived-optional",
            "unknown",
            "external-owner"
          ]
        },
        "rationale": {
          "$ref": "#/$defs/text"
        },
        "requirement_id": {
          "pattern": "^DS-REQ-",
          "type": "string"
        },
        "retention_posture": {
          "enum": [
            "owner-decision-required",
            "preserve-history",
            "rebuild-on-demand",
            "external-owner"
          ]
        },
